window.docContents[53].resolve({"/Terms/#Cvc___lean----High-Level-API-for-CVC5--Terms--Bound-variables___-lambdas___-quantifiers--Lambdas":{"contents":"Creates a lambda from some bound variables and a body.\n\nThis first example builds the bound variables list and the lambda term by hand, see below for a much\nmore concise version using smt!.\n\n#eval Env.runIO do\n  let i1 ← Term.mkSymbolAs Int \"i1\"\n  let bv_b ← BVar.mk \"b\"\n  let bv_i2 ← BVar.mk \"i2\"\n  let bv_r ← BVar.mk \"r\"\n  let bVars :=\n    BVars.empty |>.push bv_b |>.push bv_i2 |>.push bv_r\n  --  vvv~~~ `Term (Bool → Int → Rat → Bool)`\n  let lam ← Term.lambda bVars\n    (← smt! if bv_b then i1 < bv_i2 else bv_r = 0.0)\n  println! \"lam := {lam}\"\n\n  let b ← Term.mkSymbol \"b\"\n  let r ← Term.mkSymbol \"r\"\n  let solver ← Solver.new\n  solver.setOpt .smt_produceModels true\n  smt! lam b i1 r >>= solver.assert\n  solver.checkSat (ifSat := do\n    println! \"sat\"\n    println! \"- b  := {← b.getValue}\"\n    println! \"- i1 := {← i1.getValue}\"\n    println! \"- r  := {← r.getValue}\")\n\n\nlam := (lambda ((b Bool) (i2 Int) (r Real)) (ite b (< i1 i2) (= r 0.0)))\nsat\n- b  := false\n- i1 := 0\n- r  := 0\n\n\nUsing the smt! syntax extension:\n\n#eval Env.runIO do\n  let i1 ← Term.mkSymbolAs Int \"i1\"\n  let lam ← smt!\n    -- feel free to use `λ` instead of `fun`\n    fun (b : Bool) (i2 : Int) (r : Rat) =>\n      if b then i1 < i2 else r = 0.0\n  println! \"lam := {lam}\"\n\n  let b ← Term.mkSymbol \"b\"\n  let r ← Term.mkSymbol \"r\"\n  let solver ← Solver.new\n  solver.setOpt .smt_produceModels true\n  smt! lam b i1 r >>= solver.assert\n  solver.checkSat (ifSat := do\n    println! \"sat\"\n    println! \"- b  := {← b.getValue}\"\n    println! \"- i1 := {← i1.getValue}\"\n    println! \"- r  := {← r.getValue}\")\n\n\nlam := (lambda ((b Bool) (i2 Int) (r Real)) (ite b (< i1 i2) (= r 0.0)))\nsat\n- b  := false\n- i1 := 0\n- r  := 0\n\n\n","context":"Cvc.lean -- High-Level API for CVC5\u0009Terms\u0009Bound variables, lambdas, quantifiers","header":"4.4.1. Lambdas","id":"/Terms/#Cvc___lean----High-Level-API-for-CVC5--Terms--Bound-variables___-lambdas___-quantifiers--Lambdas"}});